using Microsoft.EntityFrameworkCore;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Fix 1: EF Core 9 renamed discriminator from "Discriminator" to "$type".
            // Preserve legacy property name so existing documents remain readable.
            entity.HasDiscriminator<string>("Discriminator");

            // Fix 2: EF Core 9 changed id format from "Blog|<key>" to just "<key>".
            // Preserve legacy format so existing documents remain findable.
            entity.ToContainer("Blogs");
            entity.HasPartitionKey(b => b.Id);
            entity.Property<string>("__id")
                .ToJsonProperty("id")
                .HasValueGenerator((_, _) => new LegacyCosmosIdGenerator());

            // Fix 3: HasIndex() now throws for Cosmos provider — removed.
        });
    }
}

class Blog
{
    public string Id { get; set; }
    public string Name { get; set; }
}

// Fix 2 (continued): Generates ids in legacy "Discriminator|Key" format
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    public override string Next(EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var key = entry.Property("Id").CurrentValue;
        return $"{entityType}|{key}";
    }
}

